(window.GENESIS_SOURCE_FILES ||= {})["src/spdyn/sp_energy_pme_noopt_2dalltoall.fpp"] = "!--------1---------2---------3---------4---------5---------6---------7---------8\n!\n!  Module   sp_energy_pme_noopt_2dalltoall_mod\n!> @brief   Smooth particle mesh ewald method\n!! @authors Jaewoon Jung (JJ)\n!\n!  (c) Copyright 2014 RIKEN. All rights reserved.\n!\n!--------1---------2---------3---------4---------5---------6---------7---------8\n\n#ifdef HAVE_CONFIG_H\n#include \"../config.h\"\n#endif\n\nmodule sp_energy_pme_noopt_2dalltoall_mod\n\n  use sp_boundary_str_mod\n  use sp_enefunc_str_mod\n  use sp_energy_str_mod\n  use sp_domain_str_mod\n  use math_libs_mod\n  use timers_mod\n  use messages_mod\n  use mpi_parallel_mod\n  use constants_mod\n  use fft3d_2dalltoall_mod\n#ifdef HAVE_MPI_GENESIS\n  use mpi\n#endif\n\n  implicit none\n  private\n\n  real(wp),         save :: el_fact      ! e^2/(4*pi*eps) A*kcal/mol\n  real(wp),         save :: alpha        ! alpha\n  real(wp),         save :: inv_alpha    ! 1/alpha\n  real(wp),         save :: alpha2m      ! -alpha^2\n  real(wp),         save :: alpha3       ! alpha^3\n  real(wp),         save :: alpha6       ! alpha^6\n  real(wp),         save :: vol_fact2    ! (2*pi/V)*el_fact\n  real(wp),         save :: vol_fact4    ! (4*pi/V)*el_fact\n  real(wp),         save :: vol_fact2_lj ! (sqrt(pi^3)/24V)\n  real(wp),         save :: vol_fact4_lj ! (2*sqrt(pi^3)/24V)\n  real(dp), public, save :: u_self_no2   ! Ewald self energy\n  real(wp),         save :: inv_volume\n  real(wp),         save :: box(3)       ! box size\n  real(wp),         save :: box_inv(3)   ! Inverse of box size\n  real(wp),         save :: bs_fact      ! B-spline factor (1/(n-1)...2)\n  real(wp),         save :: bs_fact3     ! bs_fact^3\n  real(wp),         save :: bs_fact3d    ! bs_fact^3*(n-1)\n  real(wp),         save :: r_scale(3)   ! coordinate-scaling factor (I/L)\n  integer,          save :: n_bs         ! Order of B-spline\n  integer, public,  save :: ngrid(3)     ! Number of grid\n  integer,          save :: nx           ! process number in x dimension\n  integer,          save :: ny           ! process number in y dimension\n  integer,          save :: nz           ! process number in z dimension\n  integer,          save :: x_start\n  integer,          save :: x_end\n  integer,          save :: x_start1\n  integer,          save :: x_end1\n  integer,          save :: x_local1 \n  integer,          save :: y_start\n  integer,          save :: y_end\n  integer,          save :: z_start\n  integer,          save :: z_end\n  integer,          save :: nlocalx\n  integer,          save :: nlocalx1\n  integer,          save :: nlocaly\n  integer,          save :: nlocalz\n  integer,          save :: maxproc\n  integer,          save :: ngridmax\n\n  real(wp),         save, allocatable :: b2(:,:)        ! b^2(hx,hy,hz)\n  real(wp),         save, allocatable :: gx(:)\n  real(wp),         save, allocatable :: gy(:)\n  real(wp),         save, allocatable :: gz(:)\n  real(wp),         save, allocatable :: vir_fact(:,:,:)! -2*(1+G^2/4a)/G^2\n  real(wp),         save, allocatable :: vir_fact_lj(:,:,:)\n  real(wp),         save, allocatable :: theta(:,:,:)   ! F^-1[Theta](hz,hy,hx,procz)\n  real(wp),         save, allocatable :: theta_lj(:,:,:) \n  real(wp),         save, allocatable :: f(:,:,:)\n  integer,          save, allocatable :: vi(:,:,:)\n  real(wp),         save, allocatable :: bsc(:,:,:,:)\n  real(wp),         save, allocatable :: bscd(:,:,:,:)\n  real(wp),         save, allocatable :: qdf(:,:,:,:)\n  real(wp),         save, allocatable :: qdf_real(:)\n  real(wp),         save, allocatable :: qdf_work(:,:)\n  real(wp),         save, allocatable :: ldf(:,:,:,:)\n  real(wp),         save, allocatable :: ldf_real(:)\n  real(wp),         save, allocatable :: ldf_work(:,:)\n  complex(wp),      save, allocatable :: ftqdf(:)\n  complex(wp),      save, allocatable :: ftqdf_work(:,:)\n  complex(wp),      save, allocatable :: ftldf(:)\n  complex(wp),      save, allocatable :: ftldf_work(:,:)\n\n  !$omp threadprivate(f)\n  !$omp threadprivate(bsc)\n  !$omp threadprivate(bscd)\n\n  complex(wp),      save, allocatable :: ftqdf_work2(:,:,:)\n  complex(wp),      save, allocatable :: ftldf_work2(:,:,:)\n\n  ! parameters\n  integer, parameter      :: NumIndex        = 45\n  integer, parameter      :: Index(NumIndex) = (/ &\n                              1,   2,   3,   4,   5,   6,   8,   9,  10,  12, &\n                             15,  16,  18,  20,  24,  25,  27,  30,  32,  36, &\n                             40,  45,  48,  50,  54,  60,  64,  72,  75,  80, &\n                             81,  90,  96, 100, 120, 125, 128, 135, 144, 150, &\n                            160, 162, 180, 192, 200/)\n\n  ! subroutines\n  public  :: setup_pme_noopt_2dalltoall\n  public  :: dealloc_pme_noopt_2dalltoall\n  public  :: pme_pre_noopt_2dalltoall\n  public  :: pme_pre_noopt_2dalltoall_lj\n  public  :: pme_recip_noopt_2dalltoall\n  public  :: pme_recip_noopt_2dalltoall_lj\n\ncontains\n\n  !======1=========2=========3=========4=========5=========6=========7=========8\n  !\n  !  Subroutine    setup_pme_noopt_2dalltoall\n  !> @brief        Setup for PME with domain decomposition\n  !! @authors      JJ, NT\n  !! @param[in]    domain   : domain information\n  !! @param[in]    boundary : boundary information\n  !! @param[in]    enefunc  : energy function\n  !\n  !======1=========2=========3=========4=========5=========6=========7=========8\n\n  subroutine setup_pme_noopt_2dalltoall(domain, boundary, enefunc)\n\n    ! formal arguments\n    type(s_domain),          intent(in)    :: domain\n    type(s_boundary),        intent(in)    :: boundary\n    type(s_enefunc),         intent(in)    :: enefunc\n\n    ! local variables\n    real(wp)                 :: bcos, bsin, fact, grid_space\n    integer                  :: i, j, k, js\n    integer                  :: localmax, ncell\n    integer                  :: iproc(3), index_x, index_y, index_z\n    integer                  :: remainder, quotient, expo\n    integer                  :: alloc_stat\n    integer                  :: nix, niy\n\n    real(wp),    allocatable :: bs(:)\n\n\n    ncell    =  domain%num_cell_local + domain%num_cell_boundary\n\n    ! Setting the number of grids (even number)\n    !\n    ngrid(1) = enefunc%pme_ngrid_x\n    ngrid(2) = enefunc%pme_ngrid_y\n    ngrid(3) = enefunc%pme_ngrid_z\n    ngridmax = max(ngrid(1),ngrid(2),ngrid(3))\n\n    if (ngrid(1) == 0 .and. ngrid(2) == 0 .and. ngrid(3) ==0) then\n\n      grid_space = enefunc%pme_max_spacing\n      ngrid(1) = int(boundary%box_size_x/grid_space)\n      ngrid(2) = int(boundary%box_size_y/grid_space)\n      ngrid(3) = int(boundary%box_size_z/grid_space)\n      ngridmax = max(ngrid(1),ngrid(2),ngrid(3))\n\n    end if\n\n    ! grid partition\n    !\n    if (reciprocal_calc) then\n\n      ! Setting common parameters\n      !\n      el_fact  = ELECOEF/enefunc%dielec_const\n      n_bs     = enefunc%pme_nspline\n      alpha    = enefunc%pme_alpha\n      alpha2m  = -alpha**2\n      alpha3    = alpha*alpha*alpha\n      alpha6    = alpha3*alpha3\n      inv_alpha = 1.0_wp / alpha\n\n      nx = boundary%num_domain(1)\n      ny = boundary%num_domain(2)\n      nz = boundary%num_domain(3)\n\n      ! Check if charges in boundary cells are sufficient for charge\n      ! grid data in each subdomain\n      !\n      grid_space = boundary%box_size_x / real(ngrid(1),wp)\n      ngridMax   = int(boundary%cell_size_x / grid_space)\n      grid_space = boundary%box_size_y / real(ngrid(2),wp)\n      ngridMax   = min(ngridMax,int(boundary%cell_size_y/grid_space))\n      grid_space = boundary%box_size_z / real(ngrid(3),wp)\n      ngridMax   = min(ngridMax,int(boundary%cell_size_z/grid_space))\n      if (ngridmax \u003c n_bs) then\n        if (.not. pme_native_requested) &\n          call error_msg('Cell size should be larger to obtain the charge'// &\n                         ' data from neighboring cells')\n        pme_mesh_native_only = .true.\n      end if\n\n     ! Check grid point in x direction\n      !\n      remainder = mod(ngrid(1),2*nx*ny)\n      if (remainder /= 0) ngrid(1) = ngrid(1) + 2*nx*ny - remainder\n\n      quotient = ngrid(1)/(2*nx*ny)\n      if (quotient \u003c= Index(NumIndex)) then\n        do i = 1, NumIndex\n          if (quotient \u003c= Index(i)) exit\n        end do\n        quotient = Index(i)\n        ngrid(1) = (2*nx*ny) * quotient\n      else\n        expo = int(log(real(quotient,wp))/log(real(2,wp)))\n        if (2**expo >= quotient) then\n          quotient = 2**expo\n        else\n          quotient = 2**(expo+1)\n        end if\n        ngrid(1) = (2*nx*ny) * quotient\n      end if\n\n      ! check grid points in y direction\n      !\n      if (mod(nz,2) == 0) then\n\n        remainder = mod(ngrid(2),ny*nz)\n        if (remainder /= 0) ngrid(2) = ngrid(2) + nz*ny - remainder\n\n        quotient = ngrid(2)/(nz*ny)\n        if (quotient \u003c= Index(NumIndex)) then\n          do i = 1, NumIndex\n            if (quotient \u003c= Index(i)) exit\n          end do\n          quotient = Index(i)\n          ngrid(2) = (nz*ny) * quotient\n        else\n          expo = int(log(real(quotient,wp))/log(real(2,wp)))\n          if (2**expo >= quotient) then\n            quotient = 2**expo\n          else\n            quotient = 2**(expo+1)\n          end if\n          ngrid(2) = (nz*ny) * quotient\n        end if\n\n      else\n\n        remainder = mod(ngrid(2),ny*nz*2)\n        if (remainder /= 0) ngrid(2) = ngrid(2) + nz*ny*2 - remainder\n\n        quotient = ngrid(2)/(nz*ny*2)\n        if (quotient \u003c= Index(NumIndex)) then\n          do i = 1, NumIndex\n            if (quotient \u003c= Index(i)) exit\n          end do\n          quotient = Index(i)\n          ngrid(2) = (nz*ny*2) * quotient\n        else\n          expo = int(log(real(quotient,wp))/log(real(2,wp)))\n          if (2**expo >= quotient) then\n            quotient = 2**expo\n          else\n            quotient = 2**(expo+1)\n          end if\n          ngrid(2) = (nz*ny*2) * quotient\n        end if\n\n      end if\n\n      ! Check grid point in z direction\n      !\n      remainder = mod(ngrid(3),nz*nx)\n      if (remainder /= 0) ngrid(3) = ngrid(3) + nz*nx - remainder\n\n      quotient = ngrid(3)/(nz*nx)\n      if (quotient \u003c= Index(NumIndex)) then\n        do i = 1, NumIndex\n          if (quotient \u003c= Index(i)) exit\n        end do\n        quotient = Index(i)\n        ngrid(3) = (nz*nx) * quotient\n      else\n        expo = int(log(real(quotient,wp))/log(real(2,wp)))\n        if (2**expo >= quotient) then\n          quotient = 2**expo\n        else\n          quotient = 2**(expo+1)\n        end if\n        ngrid(3) = (nz*nx) * quotient\n      end if\n\n      if ((enefunc%pme_ngrid_x /= ngrid(1)) .or. &\n          (enefunc%pme_ngrid_y /= ngrid(2)) .or. &\n          (enefunc%pme_ngrid_z /= ngrid(3))) then\n\n        if (main_rank) then\n          write(MsgOut,'(A)') &\n            ''\n          if (enefunc%pme_ngrid_x==0 .and. enefunc%pme_ngrid_y==0 .and. &\n              enefunc%pme_ngrid_z==0) then\n            write(MsgOut,'(A)') &\n              'Setup_PME> Proper PME grid number was generated automatically'\n          else\n            write(MsgOut,'(A)') &\n              '  WARNING: PME grid number is different from the input'\n          end if\n          write(MsgOut,'(A20,3I10)') &\n            '  pme_ngrid(x,y,z)= ', ngrid(1), ngrid(2), ngrid(3)\n          write(MsgOut,'(A)') &\n            ''\n        end if\n      end if\n\n      ngridmax = max(ngrid(1),ngrid(2),ngrid(3))\n\n      ! index for each processor\n      !\n\n      iproc(1) = mod(my_city_rank, boundary%num_domain(1))\n      iproc(2) = mod(my_city_rank/boundary%num_domain(1),boundary%num_domain(2))\n      iproc(3) = my_city_rank/(boundary%num_domain(1)*boundary%num_domain(2))\n\n      nlocalx  = int((ngrid(1)+nx-1)/nx)\n      nlocaly  = int((ngrid(2)+ny-1)/ny)\n      nlocalz  = int((ngrid(3)+nz-1)/nz)\n\n      x_start  = (iproc(1))*nlocalx + 1\n      y_start  = (iproc(2))*nlocaly + 1\n      z_start  = (iproc(3))*nlocalz + 1\n\n      x_end    = (iproc(1)+1)*nlocalx\n      y_end    = (iproc(2)+1)*nlocaly\n      z_end    = (iproc(3)+1)*nlocalz\n\n      localmax = max(nlocalx*nlocaly,nlocalx*nlocalz,nlocaly*nlocalz)\n      index_x  = iproc(2)*nlocaly*nlocalz + iproc(3)\n      index_y  = iproc(3)*nlocalx*nlocalz + iproc(1)\n      index_z  = iproc(1)*nlocalx*nlocaly + iproc(2)\n\n      maxproc = max(nprocx,nprocy,nprocz,1)\n\n      nlocalx1 = nlocalx/2 + 1\n      if (my_x_rank == 0) then\n        x_local1 = nlocalx1\n        x_start1 = 1\n        x_end1   = x_local1\n      else\n        x_local1 = nlocalx1 - 1\n        x_start1 = my_x_rank*nlocalx/2 + 2\n        x_end1   = x_start1 + x_local1 - 1\n      end if\n    end if\n\n    if (reciprocal_calc) then\n\n      j = 1\n      do i = 1, n_bs - 2\n        j = j*(n_bs - i)\n      end do\n\n      bs_fact   = 1.0_wp/real(j,wp)\n      bs_fact3  = bs_fact**3\n      bs_fact3d = bs_fact3 * real(n_bs - 1,wp)\n\n      ! Preparing b2=b(h)^2, h shifted\n      !\n      allocate(bs(n_bs), b2(ngridmax,3))\n\n      call b_spline_coef(n_bs, 1.0_wp, bs)\n\n      do i = 1, n_bs - 1\n        bs(i) = bs(i)*bs_fact\n      end do\n\n      do k = 1, 3\n\n        fact = 2.0_wp * PI/real(ngrid(k),wp)\n\n        do j = 1, ngrid(k)/2 + 1\n\n          js = j - 1\n          bcos = 0.0_wp\n          bsin = 0.0_wp\n\n          do i = 0, n_bs - 2\n            bcos = bcos + bs(i+1) * cos(real(js*i,wp)*fact)\n            bsin = bsin + bs(i+1) * sin(real(js*i,wp)*fact)\n          end do\n\n          b2(j, k) = 1.0_wp/(bcos*bcos + bsin*bsin)\n\n        end do\n\n        do j = ngrid(k)/2 + 2, ngrid(k)\n\n          js = j - 1 - ngrid(k)\n          bcos = 0.0_wp\n          bsin = 0.0_wp\n\n          do i = 0, n_bs - 2\n            bcos = bcos + bs(i+1) * cos(real(js*i,wp)*fact)\n            bsin = bsin + bs(i+1) * sin(real(js*i,wp)*fact)\n          end do\n\n          b2(j, k) = 1.0_wp/(bcos*bcos + bsin*bsin)\n\n        end do\n\n      end do\n\n      if (mod(n_bs,2) == 1) then\n        do k = 1, 3\n          b2(ngrid(k)/2 + 1,k) = 0.0_wp\n        end do\n      end if\n\n      ! Prepareing theta = F^-1[theta](h), h shifted\n      !\n      nix = (nlocalx1-1) / ny\n      niy = ngrid(2) / nz\n\n      if (enefunc%vdw == VDWPME) then\n        allocate(gx(nix+1), gy(niy), gz(ngrid(3)),      &\n                 vir_fact(ngrid(3),niy,nix+1),          &\n                 vir_fact_lj(ngrid(3),niy,nix+1),       &\n                 vi(3,MaxAtom,ncell),                   &\n                 theta(ngrid(3),niy,nix+1),             &\n                 theta_lj(ngrid(3),niy,nix+1),          &\n                 ftqdf_work2(ngrid(3),niy,nix+1),       &\n                 ftldf_work2(ngrid(3),niy,nix+1),       &\n                 qdf(nlocalx,nlocaly,nlocalz,nthread),  &\n                 qdf_real(nlocalx*nlocaly*nlocalz),     &\n                 qdf_work(nlocalx*nlocaly*nlocalz,1),   &\n                 ldf(nlocalx,nlocaly,nlocalz,nthread),  &\n                 ldf_real(nlocalx*nlocaly*nlocalz),     &\n                 ldf_work(nlocalx*nlocaly*nlocalz,1),   &\n                 ftqdf(ngrid(3)*(nix+1)*niy),           &\n                 ftqdf_work(ngrid(3)*(nix+1)*niy,1),    &\n                 ftldf(ngrid(3)*(nix+1)*niy),           &\n                 ftldf_work(ngrid(3)*(nix+1)*niy,1),    &\n                 stat = alloc_stat)\n      else\n        allocate(gx(nix+1), gy(niy), gz(ngrid(3)),      &\n                 vir_fact(ngrid(3),niy,nix+1),          &\n                 vi(3,MaxAtom,ncell),                   &\n                 theta(ngrid(3),niy,nix+1),             &\n                 ftqdf_work2(ngrid(3),niy,nix+1),       &\n                 qdf(nlocalx,nlocaly,nlocalz,nthread),  &\n                 qdf_real(nlocalx*nlocaly*nlocalz),     &\n                 qdf_work(nlocalx*nlocaly*nlocalz,1),   &\n                 ftqdf(ngrid(3)*(nix+1)*niy),           &\n                 ftqdf_work(ngrid(3)*(nix+1)*niy,1),    &\n                 stat = alloc_stat)\n      end if\n\n      if (alloc_stat /= 0) call error_msg_alloc\n\n      !$omp parallel private(alloc_stat)\n\n      allocate(f(3,MaxAtom,ncell),                                   &\n               bsc(n_bs,3,MaxAtom,ncell),bscd(n_bs,3,MaxAtom,ncell), &\n               stat = alloc_stat)\n      if (alloc_stat /= 0)   call error_msg_alloc\n\n      !$omp end parallel\n\n      deallocate(bs)\n\n    end if\n\n    return\n\n  end subroutine setup_pme_noopt_2dalltoall\n\n  !======1=========2=========3=========4=========5=========6=========7=========8\n  !\n  !  Subroutine    dealloc_pme_noopt_2dalltoall\n  !> @brief        deallocate all arrays used in PME\n  !! @authors      JJ, NT\n  !! @param[in]    enefunc : potential energy function information\n  !\n  !======1=========2=========3=========4=========5=========6=========7=========8\n\n  subroutine dealloc_pme_noopt_2dalltoall(enefunc)\n\n    type(s_enefunc),          intent(in) :: enefunc\n\n    ! local variables\n    integer :: dealloc_stat, ierr\n\n\n    if (.not. allocated(f)) &\n      return \n\n    !$omp parallel private(dealloc_stat)\n    deallocate(f, bsc, bscd, stat = dealloc_stat)\n    if (dealloc_stat /= 0) call error_msg_dealloc\n    !$omp end parallel\n\n    if (enefunc%vdw == VDWPME) then\n      deallocate(gx, gy, gz, vir_fact, vir_fact_lj, vi,        &\n                 theta, theta_lj, ftqdf_work2, ftldf_work2,    &\n                 qdf, qdf_real, qdf_work, ftqdf, ftqdf_work,   &\n                 ldf, ldf_real, ldf_work, ftldf, ftldf_work,   &\n                 stat = dealloc_stat)\n    else\n      deallocate(gx, gy, gz, vir_fact, vi, theta, ftqdf_work2, &\n                 qdf, qdf_real, qdf_work, ftqdf, ftqdf_work,   &\n                 stat = dealloc_stat)\n    end if\n    if (dealloc_stat /= 0) call error_msg_dealloc\n\n    deallocate(b2, stat = dealloc_stat)\n    if (dealloc_stat /= 0) call error_msg_dealloc\n\n    return\n\n  end subroutine dealloc_pme_noopt_2dalltoall\n\n  !======1=========2=========3=========4=========5=========6=========7=========8\n  !\n  !  Subroutine    pme_pre_noopt_2dalltoall\n  !> @brief        Prepare functions for PME calculation\n  !! @authors      JJ, NT\n  !! @param[in]    domain   : domain information\n  !! @param[in]    boundary : boundary information\n  !! @note         Extracted from setup_pme for NPT calculation\n  !\n  !======1=========2=========3=========4=========5=========6=========7=========8\n\n  subroutine pme_pre_noopt_2dalltoall(domain, boundary)\n\n    ! formal arguments\n    type(s_domain),          intent(in)    :: domain\n    type(s_boundary),        intent(in)    :: boundary\n\n    ! local variables\n    integer                  :: i, j, k, is, js, ks, ix, iy\n    integer                  :: nix, nix1, niy\n    integer                  :: ix_start, ix_end, iy_start, iy_end\n    real(wp)                 :: fact, gfact(3), g2\n\n\n    box(1) = boundary%box_size_x\n    box(2) = boundary%box_size_y\n    box(3) = boundary%box_size_z\n\n    do k = 1, 3\n      box_inv(k) = 1.0_wp / box(k)\n      r_scale(k) = real(ngrid(k),wp) * box_inv(k)\n    end do\n\n    vol_fact2 = 2.0_wp * PI * el_fact * box_inv(1)*box_inv(2)*box_inv(3)\n    vol_fact4 = 2.0_wp * vol_fact2\n\n    nix = (nlocalx1-1) / nprocy\n    nix1 = nix + 1\n    niy = ngrid(2) / nprocz\n    theta(1:ngrid(3),1:niy,1:nix1) = 0.0_wp\n\n    ! Prepareing theta = F^-1[theta](h), h shifted\n    ! Gx, Gy, Gz, and vir_fact=-2(1+G^2/4a)/G^2 are also prepared \n    ! for virial calculation\n    !\n    do k = 1, 3\n      gfact(k) = 2.0_wp * PI * box_inv(k)\n    end do\n\n    fact = 0.25_wp / alpha2m\n\n    ix_start = my_xy_rank*nix + 1\n    ix_end   = ix_start + nix - 1\n\n    niy = ngrid(2) / nprocz\n    iy_start = niy*my_z_rank + 1\n    iy_end   = iy_start + niy - 1\n\n    do i = ix_start, ix_end\n\n      ix = i - ix_start + 1\n      is = i - 1\n      gx(ix) = gfact(1) * real(is,wp)\n\n      do j = iy_start, iy_end\n\n        iy = j - iy_start + 1\n        if (j \u003c= ngrid(2)/2+1) then\n          js = j - 1\n        else\n          js = j - 1 - ngrid(2)\n        end if\n        gy(iy) = gfact(2) * real(js,wp)\n\n        do k = 1, ngrid(3)\n          if (k \u003c= ngrid(3)/2+1) then\n            ks = k - 1\n          else\n            ks = k - 1 - ngrid(3)\n          end if\n          gz(k) = gfact(3) * real(ks,wp)\n          g2 = gx(ix)*gx(ix) + gy(iy)*gy(iy) + gz(k)*gz(k)\n          if (g2 > EPS) then\n            vir_fact(k,iy,ix) = -2.0_wp * (1.0_wp - g2 * fact)/g2\n            if (g2*fact \u003c -80.0_wp) then\n              theta(k,iy,ix) = 0.0_wp\n            else\n              theta(k,iy,ix) = b2(i,1)*b2(j,2)*b2(k,3)*exp(g2 * fact) / g2\n            end if\n            if (abs(theta(k,iy,ix)) \u003c 1.0e-15) theta(k,iy,ix) = 0.0_wp\n          else\n            vir_fact(k,iy,ix) = 0.0_wp\n            theta(k,iy,ix) = 0.0_wp\n          end if\n        end do\n\n      end do\n\n    end do\n\n    if (my_xy_rank == 0) then\n      i  = ngrid(1)/2 + 1\n      is = i - 1\n      ix = nix1\n      gx(ix) = gfact(1)*real(is,wp)\n\n      do j = iy_start, iy_end\n        iy = j - iy_start + 1\n        if (j \u003c= ngrid(2)/2+1) then\n          js = j - 1\n        else\n          js = j - 1 - ngrid(2)\n        end if\n        gy(iy) = gfact(2)*real(js,wp)\n\n        do k = 1, ngrid(3)\n          if (k \u003c= ngrid(3)/2+1) then\n            ks = k - 1\n          else\n            ks = k - 1 - ngrid(3)\n          end if\n          gz(k) = gfact(3)*real(ks,wp)\n          g2 = gx(ix)**2 + gy(iy)**2 + gz(k)*gz(k)\n          if (g2 > EPS) then\n            vir_fact(k,iy,ix) = -2.0_wp*(1.0_wp-g2*fact)/g2\n            if (g2*fact \u003c -80.0_wp) then\n              theta(k,iy,ix) = 0.0_wp\n            else\n              theta(k,iy,ix) = b2(i,1)*b2(j,2)*b2(k,3)*exp(g2*fact)/g2\n            end if\n            if (abs(theta(k,iy,ix)) \u003c 1.0e-15) theta(k,iy,ix) = 0.0_wp\n          else\n            vir_fact(k,iy,ix) = 0.0_wp\n            theta(k,iy,ix) = 0.0_wp\n          end if\n        end do\n      end do\n    end if\n\n    if (my_x_rank == 0 .and. my_y_rank == 0 .and. my_z_rank == 0) &\n      theta(1,1,1) = 0.0_wp\n\n    if (my_city_rank == 0) &\n      vir_fact(1,1,1) = 0.0_wp\n\n    ! Calculating self energy\n    !\n    u_self_no2 = 0.0_dp\n\n    do i = 1, domain%num_cell_local\n      do ix = 1, domain%num_atom(i)\n        u_self_no2 = u_self_no2 + domain%charge(ix,i)*domain%charge(ix,i)\n      end do\n    end do\n\n    u_self_no2 = - u_self_no2 * el_fact * alpha/sqrt(PI)\n\n    return\n\n  end subroutine pme_pre_noopt_2dalltoall\n\n  !======1=========2=========3=========4=========5=========6=========7=========8\n  !\n  !  Subroutine    pme_pre_noopt_2dalltoall_lj\n  !> @brief        Prepare functions for PME calculation\n  !! @authors      JJ, NT\n  !! @param[in]    domain   : domain information\n  !! @param[in]    boundary : boundary information\n  !! @note         Extracted from setup_pme for NPT calculation\n  !\n  !======1=========2=========3=========4=========5=========6=========7=========8\n\n  subroutine pme_pre_noopt_2dalltoall_lj(domain, boundary)\n\n    ! formal arguments\n    type(s_domain),          intent(in)    :: domain\n    type(s_boundary),        intent(in)    :: boundary\n\n    ! local variables\n    integer                  :: i, j, k, is, js, ks, ix, iy\n    integer                  :: nix, nix1, niy\n    integer                  :: ix_start, ix_end, iy_start, iy_end\n    real(wp)                 :: fact, gfact(3), g1, g2, g3, g_lj\n    real(wp)                 :: fact1, fact2, fact3, fact4, fact5\n\n\n    box(1) = boundary%box_size_x\n    box(2) = boundary%box_size_y\n    box(3) = boundary%box_size_z\n\n    do k = 1, 3\n      box_inv(k) = 1.0_wp / box(k)\n      r_scale(k) = real(ngrid(k),wp) * box_inv(k)\n    end do\n\n    inv_volume   = box_inv(1)*box_inv(2)*box_inv(3)\n    vol_fact2    = 2.0_wp * PI * el_fact * inv_volume\n    vol_fact4    = 2.0_wp * vol_fact2\n    vol_fact2_lj = PI * sqrt(PI) * inv_volume / (24.0_wp)\n    vol_fact4_lj = 2.0_wp * vol_fact2_lj\n\n    nix = (nlocalx1-1) / nprocy\n    nix1 = nix + 1\n    niy = ngrid(2) / nprocz\n    theta(1:ngrid(3),1:niy,1:nix1) = 0.0_wp\n\n    ! Prepareing theta = F^-1[theta](h), h shifted\n    ! Gx, Gy, Gz, and vir_fact=-2(1+G^2/4a)/G^2 are also prepared \n    ! for virial calculation\n    !\n    do k = 1, 3\n      gfact(k) = 2.0_wp * PI * box_inv(k)\n    end do\n\n    fact = 0.25_wp / alpha2m\n\n    ix_start = my_xy_rank*nix + 1\n    ix_end   = ix_start + nix - 1\n\n    niy = ngrid(2) / nprocz\n    iy_start = niy*my_z_rank + 1\n    iy_end   = iy_start + niy - 1\n\n    do i = ix_start, ix_end\n\n      ix = i - ix_start + 1\n      is = i - 1\n      gx(ix) = gfact(1) * real(is,wp)\n\n      do j = iy_start, iy_end\n\n        iy = j - iy_start + 1\n        if (j \u003c= ngrid(2)/2+1) then\n          js = j - 1\n        else\n          js = j - 1 - ngrid(2)\n        end if\n        gy(iy) = gfact(2) * real(js,wp)\n\n        do k = 1, ngrid(3)\n          if (k \u003c= ngrid(3)/2+1) then\n            ks = k - 1\n          else\n            ks = k - 1 - ngrid(3)\n          end if\n          gz(k) = gfact(3) * real(ks,wp)\n          g2 = gx(ix)*gx(ix) + gy(iy)*gy(iy) + gz(k)*gz(k)\n          g1 = sqrt(g2)\n          g3 = g1 * g2\n\n          ! -g^2/(4*alpha^2)\n          !\n          fact1 = g2*fact\n\n          ! exp(-g^2/(4*alpha^2))\n          !\n          fact2 = exp(fact1)\n\n          ! g / (2*alpha)\n          !\n          fact3 = 0.5*g1*inv_alpha\n\n          ! erfc(g/(2*alpha))\n          !\n          fact4 = erfc(fact3)\n\n          ! |bx(mx)|^2 * |by(my)|^2 * |bz(mz)|^2\n          !\n          fact5 = b2(i,1)*b2(j,2)*b2(k,3)\n\n          ! calculate theta (prefacor in the reciprocal energy) &\n          ! calculate vir_fact (prefacor in the reciprocal force)\n          !\n          g_lj = (4.0_wp*alpha3-2.0_wp*alpha*g2)*fact2 &\n               + SQRT_PI*g3*fact4\n          theta_lj(k,iy,ix) = fact5 * g_lj\n          vir_fact_lj(k,iy,ix) = 3.0_wp*g1*SQRT_PI*fact4-6.0_wp*alpha*fact2\n          vir_fact_lj(k,iy,ix) = vir_fact_lj(k,iy,ix) * fact5\n\n          if (g2 > EPS) then\n            vir_fact(k,iy,ix) = -2.0_wp * (1.0_wp - fact1)/g2\n            theta(k,iy,ix) = fact5 * fact2 / g2\n            if (abs(theta(k,iy,ix)) \u003c 1.0e-15) theta(k,iy,ix) = 0.0_wp\n          else\n            vir_fact(k,iy,ix) = 0.0_wp\n            theta(k,iy,ix) = 0.0_wp\n          end if\n        end do\n\n      end do\n\n    end do\n\n    if (my_xy_rank == 0) then\n      i  = ngrid(1)/2 + 1\n      is = i - 1\n      ix = nix1\n      gx(ix) = gfact(1)*real(is,wp)\n\n      do j = iy_start, iy_end\n        iy = j - iy_start + 1\n        if (j \u003c= ngrid(2)/2+1) then\n          js = j - 1\n        else\n          js = j - 1 - ngrid(2)\n        end if\n        gy(iy) = gfact(2)*real(js,wp)\n\n        do k = 1, ngrid(3)\n          if (k \u003c= ngrid(3)/2+1) then\n            ks = k - 1\n          else\n            ks = k - 1 - ngrid(3)\n          end if\n          gz(k) = gfact(3)*real(ks,wp)\n          g2 = gx(ix)**2 + gy(iy)**2 + gz(k)*gz(k)\n          g1 = sqrt(g2)\n          g3 = g1 * g2\n\n          ! -g^2/(4*alpha^2)\n          !\n          fact1 = g2*fact\n\n          ! exp(-g^2/(4*alpha^2))\n          !\n          fact2 = exp(fact1)\n\n          ! g / (2*alpha)\n          !\n          fact3 = 0.5*g1*inv_alpha\n\n          ! erfc(g/(2*alpha))\n          !\n          fact4 = erfc(fact3)\n\n          ! |bx(mx)|^2 * |by(my)|^2 * |bz(mz)|^2\n          !\n          fact5 = b2(i,1)*b2(j,2)*b2(k,3)\n\n          ! calculate theta (prefacor in the reciprocal energy) &\n          ! calculate vir_fact (prefacor in the reciprocal force)\n          !\n          g_lj = (4.0_wp*alpha3-2.0_wp*alpha*g2)*fact2 &\n               + SQRT_PI*g3*fact4\n          theta_lj(k,iy,ix) = fact5 * g_lj\n          vir_fact_lj(k,iy,ix) = 3.0_wp*g1*SQRT_PI*fact4-6.0_wp*alpha*fact2\n          vir_fact_lj(k,iy,ix) = vir_fact_lj(k,iy,ix) * fact5\n\n          if (g2 > EPS) then\n            vir_fact(k,iy,ix) = -2.0_wp*(1.0_wp-fact1)/g2\n            theta(k,iy,ix) = fact5 * fact2 / g2\n            if (abs(theta(k,iy,ix)) \u003c 1.0e-15) theta(k,iy,ix) = 0.0_wp\n          else\n            vir_fact(k,iy,ix) = 0.0_wp\n            theta(k,iy,ix) = 0.0_wp\n          end if\n        end do\n      end do\n    end if\n\n    if (my_x_rank == 0 .and. my_y_rank == 0 .and. my_z_rank == 0) &\n      theta(1,1,1) = 0.0_wp\n      theta_lj(1,1,1) = 0.0_wp\n\n    if (my_city_rank == 0) &\n      vir_fact(1,1,1) = 0.0_wp\n      vir_fact_lj(1,1,1) = 0.0_wp\n\n    ! Calculating self energy\n    !\n    u_self_no2 = 0.0_dp\n\n    do i = 1, domain%num_cell_local\n      do ix = 1, domain%num_atom(i)\n        u_self_no2 = u_self_no2 + domain%charge(ix,i)*domain%charge(ix,i)\n      end do\n    end do\n\n    u_self_no2 = - u_self_no2 * el_fact * alpha/sqrt(PI)\n\n    return\n\n  end subroutine pme_pre_noopt_2dalltoall_lj\n\n  !======1=========2=========3=========4=========5=========6=========7=========8\n  !\n  !  Subroutine    pme_recip_noopt_2dalltoall\n  !> @brief        Calculate PME reciprocal part with domain decomposition\n  !! @authors      JJ, NT\n  !! @param[in]    domain : domain information\n  !! @param[inout] force  : forces of target systems\n  !! @param[inout] virial : virial term of target systems\n  !! @param[inout] eelec  : electrostatic energy of target systems\n  !\n  !======1=========2=========3=========4=========5=========6=========7=========8\n\n  subroutine pme_recip_noopt_2dalltoall(domain, force, virial, eelec)\n\n    ! formal arguments\n    type(s_domain),  target, intent(in)    :: domain\n    real(wip),               intent(inout) :: force(:,:,:)\n    real(dp),                intent(inout) :: virial(3,3,nthread)\n    real(dp),                intent(inout) :: eelec(nthread)\n\n    ! local variables\n    real(wp)                 :: elec_temp\n    real(wp)                 :: vr(3), dv(3), grid(3), half_grid(3)\n    real(wp)                 :: bsc_tmp(3,n_bs), bscd_tmp(3,n_bs)\n    real(wp)                 :: vxx, vyy, vzz, temp\n    real(wp)                 :: tqq, qtmp\n    real(wp)                 :: force_local(3)\n    real(wp)                 :: vol_factor\n    integer                  :: i, k, k1, icel, iproc, id\n    integer                  :: ix, iv, iy, iz, ixs, iys, izs\n    integer                  :: ixyz, nix, nix1, niy, niz, nizx, nizy\n    integer                  :: ixx, iyy, izz, ii(3), is(n_bs,3)\n    integer                  :: start(3), end(3)\n    integer                  :: vx_tmp(n_bs), vy_tmp(n_bs), vz_tmp(n_bs)\n    integer                  :: ncell, ncell_local, omp_get_thread_num\n    integer                  :: kk, iorg, k_f, k_t\n    integer                  :: iprocx, iprocy\n    integer                  :: ix_start, ix_end, iz_start, iz_end\n\n    complex(wp), allocatable :: work1(:), work2(:)\n    real(wip),       pointer :: coord(:,:,:)\n    real(wp),        pointer :: charge(:,:)\n    integer,         pointer :: natom(:)\n\n\n    coord  => domain%coord\n    charge => domain%charge\n    natom  => domain%num_atom\n\n    ncell  = domain%num_cell_local + domain%num_cell_boundary\n    ncell_local  = domain%num_cell_local\n\n    ! Initializing the energy and force\n    !\n    qdf_real(1:nlocalx*nlocaly*nlocalz) = 0.0_wp\n\n    !$omp parallel default(shared)                                             &\n    !$omp private(id, i, iv, ix, iy, iz, icel, k, ii, dv, izz, izs, iyy, iys,  &\n    !$omp         iz_start, iz_end, ix_start, ix_end, iorg, k_f, k_t,          &\n    !$omp         ixx, ixs, vxx, vyy, vzz, iproc, tqq, k1, temp, vr, &\n    !$omp         work1, work2, elec_temp, force_local, ixyz, vx_tmp, vy_tmp,  &\n    !$omp         vz_tmp, nix, nix1, niy, niz, bsc_tmp, bscd_tmp, kk, iprocx,  &\n    !$omp         iprocy, qtmp, grid, half_grid, is, start, end, nizx, nizy)\n    !\n#ifdef OMP\n    id = omp_get_thread_num()\n#else\n    id = 0\n#endif\n\n    ! initialization\n    !\n    allocate(work1(ngridmax), work2(2*ngridmax))\n\n    start(1) = x_start\n    start(2) = y_start\n    start(3) = z_start\n    end(1) = x_end\n    end(2) = y_end\n    end(3) = z_end\n\n    ! Initialization of Q-fanction\n    !\n    do iz = 1, nlocalz\n      do iy = 1, nlocaly\n        do ix = 1, nlocalx\n          qdf(ix,iy,iz,id+1) = 0.0_wp\n        end do\n      end do\n    end do\n\n    ! Calculateing Q-fanction\n    !\n    grid(1:3) = real(ngrid(1:3),wp)\n    half_grid(1:3) = real(ngrid(1:3)/2,wp)\n\n    do icel = id+1, ncell_local, nthread\n      do i = 1, natom(icel)\n\n        qtmp = charge(i,icel)\n        vr(1:3) = coord(1:3,i,icel) * r_scale(1:3)\n        vr(1:3) = vr(1:3) + half_grid(1:3) &\n                - grid(1:3)*anint(vr(1:3)/grid(1:3))\n\n        do k = 1, 3\n          vr(k) = min(vr(k),grid(k)-0.000001_wp)\n          ii(k) = min(int(vr(k)),ngrid(k)-1)\n        end do\n\n        nix = 0\n        niy = 0\n        niz = 0\n!ocl nosimd\n        do ixyz = 1, n_bs\n          ixs = ii(1) - ixyz + 2\n          if (ixs \u003c= 0) ixs = ixs + ngrid(1)\n          if (ixs >= x_start .and. ixs \u003c= x_end) then\n            nix = nix + 1\n            vx_tmp(nix) = ixs - x_start + 1\n            is(nix,1) = ixyz\n          end if\n        end do\n\n!ocl nosimd\n        do ixyz = 1, n_bs\n          iys = ii(2) - ixyz + 2\n          if (iys \u003c= 0) iys = iys + ngrid(2)\n          if (iys >= y_start .and. iys \u003c= y_end) then\n            niy = niy + 1\n            vy_tmp(niy) = iys - y_start + 1\n            is(niy,2) = ixyz\n          end if\n        end do\n\n!ocl nosimd\n        do ixyz = 1, n_bs\n          izs = ii(3) - ixyz + 2\n          if (izs \u003c= 0) izs = izs + ngrid(3)\n          if (izs >= z_start .and. izs \u003c= z_end) then\n            niz = niz + 1\n            vz_tmp(niz) = izs - z_start + 1\n            is(niz,3) = ixyz\n          end if\n        end do\n\n        force(1,i,icel) = 1.0_wp\n\n        do k = 1, 3\n          vi(k,i,icel) = ii(k)\n          dv(k) = vr(k) - real(ii(k),wp)\n          call b_spline_dev_coef(n_bs, dv(k), bsc(1,k,i,icel), bscd(1,k,i,icel))\n        end do\n\n!ocl nosimd\n        do ix = 1, nix\n          ixyz = is(ix,1)\n          bsc_tmp(1,ix) = bsc(ixyz,1,i,icel)\n        end do\n!ocl nosimd\n        do iy = 1, niy\n          ixyz = is(iy,2)\n          bsc_tmp(2,iy) = bsc(ixyz,2,i,icel)\n        end do\n!ocl nosimd\n        do iz = 1, niz\n          ixyz = is(iz,3)\n          bsc_tmp(3,iz) = bsc(ixyz,3,i,icel)\n        end do\n\n!ocl nosimd\n        do iz = 1, niz\n          izs = vz_tmp(iz)\n          do iy = 1, niy\n            iys = vy_tmp(iy)\n!ocl norecurrence(qdf)\n             do ix = 1, nix\n               ixs = vx_tmp(ix)\n              qdf(ixs,iys,izs,id+1) = qdf(ixs,iys,izs,id+1)           &\n                                    + bsc_tmp(1,ix)*bsc_tmp(2,iy)     &\n                                     * bsc_tmp(3,iz)*qtmp   &\n                                     * bs_fact3\n            end do\n          end do\n        end do\n      end do\n    end do\n\n    do icel = id+ncell_local+1, ncell, nthread\n      do i = 1, natom(icel)\n\n        qtmp = charge(i,icel)\n        vr(1:3) = coord(1:3,i,icel) * r_scale(1:3)\n        vr(1:3) = vr(1:3) + half_grid(1:3) &\n                - grid(1:3)*anint(vr(1:3)/grid(1:3))\n\n!ocl nosimd\n        do k = 1, 3\n          vr(k) = min(vr(k),grid(k)-0.000001_wp)\n          ii(k) = min(int(vr(k)),ngrid(k)-1)\n        end do\n\n        nix = 0\n        niy = 0\n        niz = 0\n\n        ixs = ii(1) - n_bs + 2\n        if (ixs \u003c= 0) ixs = ixs + ngrid(1)\n        if (ixs >= x_start .and. ixs \u003c= x_end) then\n          nix = nix + 1\n          vx_tmp(nix) = ixs - x_start + 1\n          is (nix,1) = n_bs\n        end if\n        ixs = ii(1) + 1\n        if (ixs \u003c= 0) ixs = ixs + ngrid(1)\n        if (ixs >= x_start .and. ixs \u003c= x_end) then\n          nix = nix + 1\n          vx_tmp(nix) = ixs - x_start + 1\n          is (nix,1) = 1\n        end if\n        if (nix == 0) cycle\n\n        iys = ii(2) - n_bs + 2\n        if (iys \u003c= 0) iys = iys + ngrid(2)\n        if (iys >= y_start .and. iys \u003c= y_end) then\n          niy = niy + 1\n          vy_tmp(niy) = iys - y_start + 1\n          is (niy,2) = n_bs\n        end if\n        iys = ii(2) + 1\n        if (iys \u003c= 0) iys = iys + ngrid(2)\n        if (iys >= y_start .and. iys \u003c= y_end) then\n          niy = niy + 1\n          vy_tmp(niy) = iys - y_start + 1\n          is (niy,2) = 1\n        end if\n        if (niy == 0) cycle\n\n        izs = ii(3) - n_bs + 2\n        if (izs \u003c= 0) izs = izs + ngrid(3)\n        if (izs >= z_start .and. izs \u003c= z_end) then\n          niz = niz + 1\n          vz_tmp(niz) = izs - z_start + 1\n          is (niz,3) = n_bs\n        end if\n        izs = ii(3) + 1\n        if (izs \u003c= 0) izs = izs + ngrid(3)\n        if (izs >= z_start .and. izs \u003c= z_end) then\n          niz = niz + 1\n          vz_tmp(niz) = izs - z_start + 1\n          is (niz,3) = 1\n        end if\n        if (niz == 0) cycle\n\n!ocl nosimd\n        do ixyz = 2, n_bs-1\n          ixs = ii(1) - ixyz + 2\n          if (ixs \u003c= 0) ixs = ixs + ngrid(1)\n          if (ixs >= x_start .and. ixs \u003c= x_end) then\n            nix = nix + 1\n            vx_tmp(nix) = ixs - x_start + 1\n            is(nix,1) = ixyz\n          end if\n        end do\n\n!ocl nosimd\n        do ixyz = 2, n_bs-1\n          iys = ii(2) - ixyz + 2\n          if (iys \u003c= 0) iys = iys + ngrid(2)\n          if (iys >= y_start .and. iys \u003c= y_end) then\n            niy = niy + 1\n            vy_tmp(niy) = iys - y_start + 1\n            is(niy,2) = ixyz\n          end if\n        end do\n\n!ocl nosimd\n        do ixyz = 2, n_bs-1\n          izs = ii(3) - ixyz + 2\n          if (izs \u003c= 0) izs = izs + ngrid(3)\n          if (izs >= z_start .and. izs \u003c= z_end) then\n            niz = niz + 1\n            vz_tmp(niz) = izs - z_start + 1\n            is(niz,3) = ixyz\n          end if\n        end do\n\n        force(1,i,icel) = 1.0_wp\n\n        do k = 1, 3\n          vi(k,i,icel) = ii(k)\n          dv(k) = vr(k) - real(ii(k),wp)\n          call b_spline_dev_coef(n_bs, dv(k), bsc(1,k,i,icel), bscd(1,k,i,icel))\n        end do\n\n!ocl nosimd\n        do ix = 1, nix\n          ixyz = is(ix,1)\n          bsc_tmp(1,ix) = bsc(ixyz,1,i,icel)\n        end do\n!ocl nosimd\n        do iy = 1, niy\n          ixyz = is(iy,2)\n          bsc_tmp(2,iy) = bsc(ixyz,2,i,icel)\n        end do\n!ocl nosimd\n        do iz = 1, niz\n          ixyz = is(iz,3)\n          bsc_tmp(3,iz) = bsc(ixyz,3,i,icel)\n        end do\n\n!ocl nosimd\n        do iz = 1, niz\n          izs = vz_tmp(iz)\n          do iy = 1, niy\n            iys = vy_tmp(iy)\n!ocl norecurrence(qdf)\n             do ix = 1, nix\n               ixs = vx_tmp(ix)\n              qdf(ixs,iys,izs,id+1) = qdf(ixs,iys,izs,id+1)           &\n                                    + bsc_tmp(1,ix)*bsc_tmp(2,iy)     &\n                                     * bsc_tmp(3,iz)*qtmp   &\n                                     * bs_fact3\n            end do\n          end do\n        end do\n      end do\n    end do\n    !$omp barrier\n    do iproc = 1, nthread\n      !$omp do\n      do iz = 1, nlocalz\n        do iy = 1, nlocaly\n          k = (iy-1)*nlocalx + (iz-1)*nlocalx*nlocaly\n!ocl nosimd\n          do ix = 1, nlocalx\n            qdf_real(k+ix) = qdf_real(k+ix) + qdf(ix,iy,iz,iproc)\n          end do\n        end do\n      end do\n    end do\n\n    ! FFT (forward)\n    !\n    !$omp barrier\n    !$omp master\n#ifdef HAVE_MPI_GENESIS\n    call mpi_alltoall(qdf_real, nlocalx*nlocaly*nlocalz/nprocx, mpi_wp_real, &\n                      qdf_work, nlocalx*nlocaly*nlocalz/nprocx, mpi_wp_real, &\n                      grid_commx, ierror)\n#else\n    qdf_work(1:nlocalx*nlocaly*nlocalz,1) = qdf_real(1:nlocalx*nlocaly*nlocalz)\n#endif\n    !$omp end master\n    !$omp barrier\n\n    niz = nlocalz / nprocx\n    nix  = (nlocalx1-1)/nprocy\n    nix1 = nix + 1\n    niy = ngrid(2)/nprocz\n    call fft3d_2d_alltoall(qdf_work, ftqdf, ftqdf, ftqdf, ftqdf_work,      &\n                           ftqdf_work, ftqdf_work2, work1, work2,          &\n                           nlocalx, nlocaly, nlocalz, ngrid(1), ngrid(2),  &\n                           ngrid(3), nprocx, nprocy, nprocz, nix, nix1,    &\n                           niz, niy, id, nthread, my_x_rank, grid_commz,   &\n                           grid_commxy)\n\n    ! Energy calculation\n    !\n    iproc = my_z_rank + 1\n\n    !$omp barrier\n    !$omp do\n    do ix = 1, nix\n      do iy = 1, niy\n        elec_temp = 0.0_wp\n        vxx = 0.0_wp\n        vyy = 0.0_wp\n        vzz = 0.0_wp\n        do iz = 1, ngrid(3)\n          tqq = real(ftqdf_work2(iz,iy,ix),wp)**2 + imag(ftqdf_work2(iz,iy,ix))**2\n          tqq = tqq * theta(iz,iy,ix) * vol_fact4\n          elec_temp = elec_temp + tqq\n          vxx = vxx + tqq * (1.0_wp+vir_fact(iz,iy,ix)*gx(ix)*gx(ix))\n          vyy = vyy + tqq * (1.0_wp+vir_fact(iz,iy,ix)*gy(iy)*gy(iy))\n          vzz = vzz + tqq * (1.0_wp+vir_fact(iz,iy,ix)*gz(iz)*gz(iz))\n        end do\n        eelec(id+1) = eelec(id+1) + elec_temp\n        virial(1,1,id+1) = virial(1,1,id+1) + vxx\n        virial(2,2,id+1) = virial(2,2,id+1) + vyy\n        virial(3,3,id+1) = virial(3,3,id+1) + vzz\n      end do\n    end do\n\n    if(my_x_rank == 0 .and. my_y_rank == 0) then\n\n      !$omp do\n      do iy = 1, niy\n        elec_temp = 0.0_wp\n        vxx = 0.0_wp\n        vyy = 0.0_wp\n        vzz = 0.0_wp\n        do iz = 1, ngrid(3)\n          tqq = real(ftqdf_work2(iz,iy,1),wp)**2 + imag(ftqdf_work2(iz,iy,1))**2\n          tqq = tqq * theta(iz,iy,1) * vol_fact2\n          elec_temp = elec_temp - tqq\n          vxx = vxx - tqq * (1.0_wp+vir_fact(iz,iy,1)*gx(1)*gx(1))\n          vyy = vyy - tqq * (1.0_wp+vir_fact(iz,iy,1)*gy(iy)*gy(iy))\n          vzz = vzz - tqq * (1.0_wp+vir_fact(iz,iy,1)*gz(iz)*gz(iz))\n        end do\n        do iz = 1, ngrid(3)\n          tqq = real(ftqdf_work2(iz,iy,nix1),wp)**2 + imag(ftqdf_work2(iz,iy,nix1))**2\n          tqq = tqq * theta(iz,iy,nix1) * vol_fact2\n          elec_temp = elec_temp + tqq\n          vxx = vxx + tqq * (1.0_wp+vir_fact(iz,iy,nix1)*gx(nix1)*gx(nix1))\n          vyy = vyy + tqq * (1.0_wp+vir_fact(iz,iy,nix1)*gy(iy)*gy(iy))\n          vzz = vzz + tqq * (1.0_wp+vir_fact(iz,iy,nix1)*gz(iz)*gz(iz))\n        end do\n        eelec(id+1) = eelec(id+1) + elec_temp\n        virial(1,1,id+1) = virial(1,1,id+1) + vxx\n        virial(2,2,id+1) = virial(2,2,id+1) + vyy\n        virial(3,3,id+1) = virial(3,3,id+1) + vzz\n      end do\n    end if\n\n    ! F^-1[Th]*F^-1[Q] (=X)\n    !\n    !$omp barrier\n    !$omp do\n    do ix = 1, nix\n      do iy = 1, niy\n        do iz = 1, ngrid(3)\n          ftqdf_work2(iz,iy,ix) = ftqdf_work2(iz,iy,ix) &\n                                 * cmplx(theta(iz,iy,ix),0.0_wp,kind=wp)\n        end do\n      end do\n    end do\n    if(my_x_rank == 0 .and. my_y_rank == 0) then\n      ix = nix1\n      !$omp do\n      do iy = 1, niy\n        do iz = 1, ngrid(3)\n          ftqdf_work2(iz,iy,ix) = ftqdf_work2(iz,iy,ix) * cmplx(theta(iz,iy,ix),0.0_wp,kind=wp)\n        end do\n      end do\n    end if\n\n    ! FFT(backward)\n    ! \n    !$omp barrier\n    call bfft3d_2d_alltoall(qdf_work, qdf_real, ftqdf, ftqdf, ftqdf,       &\n                            ftqdf_work, ftqdf_work, ftqdf_work2, work1,    &\n                            work2, nlocalx, nlocaly, nlocalz,              &\n                            ngrid(1), ngrid(2), ngrid(3),                  &\n                            nprocx, nprocy, nprocz, nix, nix1, niy, niz,   &\n                            id, nthread, grid_commx, grid_commz, grid_commxy)\n\n    !$omp barrier\n\n    do iz = id+1, nlocalz, nthread\n      do iy = 1, nlocaly\n        k = (iy-1)*nlocalx + (iz-1)*nlocalx*nlocaly\n        do ix = 1, nlocalx\n          qdf(ix,iy,iz,1) = qdf_real(k+ix)\n        end do\n      end do\n    end do\n\n    !$omp barrier\n\n    do icel = id+1, ncell_local, nthread\n      do i = 1, natom(icel)\n\n        force_local(1:3) = 0.0_wp\n        qtmp = charge(i,icel)\n\n!ocl nosimd\n        do k = 1, 3\n          ii(k) = vi(k,i,icel)\n        end do\n\n        nix=0\n        niy=0\n        niz=0\n\n!ocl nosimd\n        do ixyz = 1, n_bs\n\n          ixs = ii(1) - (ixyz-1) + 1\n          iys = ii(2) - (ixyz-1) + 1\n          izs = ii(3) - (ixyz-1) + 1\n          if (ixs \u003c= 0) ixs = ixs + ngrid(1)\n          if (iys \u003c= 0) iys = iys + ngrid(2)\n          if (izs \u003c= 0) izs = izs + ngrid(3)\n\n          if (ixs >= x_start .and. ixs \u003c= x_end) then\n            nix = nix + 1\n            vx_tmp(nix) = ixs - x_start + 1\n            bsc_tmp(1,nix)  = bsc(ixyz,1,i,icel)\n            bscd_tmp(1,nix) = bscd(ixyz,1,i,icel)\n          end if\n\n          if (iys >= y_start .and. iys \u003c= y_end) then\n            niy = niy + 1\n            vy_tmp(niy) = iys - y_start + 1\n            bsc_tmp(2,niy)  = bsc(ixyz,2,i,icel)\n            bscd_tmp(2,niy) = bscd(ixyz,2,i,icel)\n          end if\n\n          if (izs >= z_start .and. izs \u003c= z_end) then\n            niz = niz + 1\n            vz_tmp(niz) = izs - z_start + 1\n            bsc_tmp(3,niz)  = bsc(ixyz,3,i,icel)\n            bscd_tmp(3,niz) = bscd(ixyz,3,i,icel)\n          end if\n        end do\n\n!ocl nosimd\n        do iz = 1, niz\n          izs = vz_tmp(iz)\n          do iy = 1, niy\n            iys = vy_tmp(iy)\n            do ix = 1, nix\n              ixs = vx_tmp(ix)\n\n              force_local(1) = force_local(1)            &\n                  + bscd_tmp(1,ix)*bsc_tmp(2,iy)         &\n                  * bsc_tmp(3,iz)*qdf(ixs,iys,izs,1)\n              force_local(2) = force_local(2)            &\n                  + bsc_tmp(1,ix)*bscd_tmp(2,iy)         &\n                  * bsc_tmp(3,iz)*qdf(ixs,iys,izs,1)\n              force_local(3) = force_local(3)            &\n                  + bsc_tmp(1,ix)*bsc_tmp(2,iy)          &\n                  * bscd_tmp(3,iz)*qdf(ixs,iys,izs,1)\n            end do\n          end do\n        end do\n\n        force(1:3,i,icel) = - force_local(1:3) * &\n                              qtmp*r_scale(1:3)*vol_fact4*bs_fact3d\n\n      end do\n    end do\n\n    do icel = id+ncell_local+1, ncell, nthread\n      do i = 1, natom(icel)\n\n        if (abs(force(1,i,icel)) \u003c EPS) cycle\n\n        force_local(1:3) = 0.0_wp\n        qtmp = charge(i,icel)\n\n!ocl nosimd\n        do k = 1, 3\n          ii(k) = vi(k,i,icel)\n        end do\n\n        nix=0\n        niy=0\n        niz=0\n\n!ocl nosimd\n        do ixyz = 1, n_bs\n\n          ixs = ii(1) - (ixyz-1) + 1\n          iys = ii(2) - (ixyz-1) + 1\n          izs = ii(3) - (ixyz-1) + 1\n          if (ixs \u003c= 0) ixs = ixs + ngrid(1)\n          if (iys \u003c= 0) iys = iys + ngrid(2)\n          if (izs \u003c= 0) izs = izs + ngrid(3)\n\n          if (ixs >= x_start .and. ixs \u003c= x_end) then\n            nix = nix + 1\n            vx_tmp(nix) = ixs - x_start + 1\n            bsc_tmp(1,nix)  = bsc(ixyz,1,i,icel)\n            bscd_tmp(1,nix) = bscd(ixyz,1,i,icel)\n          end if\n\n          if (iys >= y_start .and. iys \u003c= y_end) then\n            niy = niy + 1\n            vy_tmp(niy) = iys - y_start + 1\n            bsc_tmp(2,niy)  = bsc(ixyz,2,i,icel)\n            bscd_tmp(2,niy) = bscd(ixyz,2,i,icel)\n          end if\n\n          if (izs >= z_start .and. izs \u003c= z_end) then\n            niz = niz + 1\n            vz_tmp(niz) = izs - z_start + 1\n            bsc_tmp(3,niz)  = bsc(ixyz,3,i,icel)\n            bscd_tmp(3,niz) = bscd(ixyz,3,i,icel)\n          end if\n        end do\n\n!ocl nosimd\n        do iz = 1, niz\n          izs = vz_tmp(iz)\n          do iy = 1, niy\n            iys = vy_tmp(iy)\n            do ix = 1, nix\n              ixs = vx_tmp(ix)\n\n              force_local(1) = force_local(1)            &\n                  + bscd_tmp(1,ix)*bsc_tmp(2,iy)         &\n                  * bsc_tmp(3,iz)*qdf(ixs,iys,izs,1)\n              force_local(2) = force_local(2)            &\n                  + bsc_tmp(1,ix)*bscd_tmp(2,iy)         &\n                  * bsc_tmp(3,iz)*qdf(ixs,iys,izs,1)\n              force_local(3) = force_local(3)            &\n                  + bsc_tmp(1,ix)*bsc_tmp(2,iy)          &\n                  * bscd_tmp(3,iz)*qdf(ixs,iys,izs,1)\n            end do\n          end do\n        end do\n\n        force(1:3,i,icel) = - force_local(1:3) * &\n                              qtmp*r_scale(1:3)*vol_fact4*bs_fact3d\n\n      end do\n    end do\n\n    deallocate(work1, work2)\n\n    !$omp end parallel\n\n    return\n\n  end subroutine pme_recip_noopt_2dalltoall\n\n  !======1=========2=========3=========4=========5=========6=========7=========8\n  !\n  !  Subroutine    pme_recip_noopt_2dalltoall_lj\n  !> @brief        Calculate PME reciprocal part with domain decomposition\n  !! @authors      JJ, NT\n  !! @param[in]    domain  : domain information\n  !! @param[in]    enefunc : potential energy function information\n  !! @param[inout] force   : forces of target systems\n  !! @param[inout] virial  : virial term of target systems\n  !! @param[inout] eelec   : electrostatic energy of target systems\n  !! @param[inout] evdw    : van der Waals energy of target systems\n  !\n  !======1=========2=========3=========4=========5=========6=========7=========8\n\n  subroutine pme_recip_noopt_2dalltoall_lj(domain, enefunc, force, virial, &\n                                           eelec, evdw)\n\n    ! formal arguments\n    type(s_domain),  target, intent(in)    :: domain\n    type(s_enefunc), target, intent(in)    :: enefunc\n    real(wip),               intent(inout) :: force(:,:,:)\n    real(dp),                intent(inout) :: virial(3,3,nthread)\n    real(dp),                intent(inout) :: eelec(nthread)\n    real(dp),                intent(inout) :: evdw(nthread)\n\n    ! local variables\n    real(wp)                 :: elec_temp, evdw_temp\n    real(wp)                 :: vr(3), dv(3), grid(3), half_grid(3)\n    real(wp)                 :: bsc_tmp(3,n_bs), bscd_tmp(3,n_bs)\n    real(wp)                 :: vxx, vyy, vzz, temp\n    real(wp)                 :: efft_real, efft_imag\n    real(wp)                 :: vfft_real, vfft_imag\n    real(wp)                 :: tqq, tll, qtmp, ltmp\n    real(wp)                 :: force_local(3), force_local_lj(3)\n    real(wp)                 :: vol_factor\n    integer                  :: iatmcls\n    integer                  :: i, k, k1, icel, iproc, id\n    integer                  :: ix, iv, iy, iz, ixs, iys, izs\n    integer                  :: ixyz, nix, nix1, niy, niz, nizx, nizy\n    integer                  :: ixx, iyy, izz, ii(3), is(n_bs,3)\n    integer                  :: start(3), end(3)\n    integer                  :: vx_tmp(n_bs), vy_tmp(n_bs), vz_tmp(n_bs)\n    integer                  :: ncell, ncell_local, omp_get_thread_num\n    integer                  :: kk, iorg, k_f, k_t\n    integer                  :: iprocx, iprocy\n    integer                  :: ix_start, ix_end, iz_start, iz_end\n\n    complex(wp), allocatable :: work1(:), work2(:), work3(:), work4(:)\n    real(wip),       pointer :: coord(:,:,:)\n    real(wp),        pointer :: charge(:,:)\n    real(wp),        pointer :: nonb_lj6_factor(:)\n    integer,         pointer :: natom(:)\n    integer,         pointer :: atmcls(:,:)\n\n\n    coord  => domain%coord\n    charge => domain%charge\n    natom  => domain%num_atom\n    atmcls          => domain%atom_cls_no\n    nonb_lj6_factor => enefunc%nonb_lj6_factor\n\n    ncell  = domain%num_cell_local + domain%num_cell_boundary\n    ncell_local  = domain%num_cell_local\n\n    ! Initializing the energy and force\n    !\n    qdf_real(1:nlocalx*nlocaly*nlocalz) = 0.0_wp\n    ldf_real(1:nlocalx*nlocaly*nlocalz) = 0.0_wp\n\n    !$omp parallel default(shared)                                             &\n    !$omp private(id, i, iv, ix, iy, iz, icel, k, ii, dv, izz, izs, iyy, iys,  &\n    !$omp         iz_start, iz_end, ix_start, ix_end, iorg, k_f, k_t,          &\n    !$omp         ixx, ixs, vxx, vyy, vzz, iproc, tqq, tll, k1, temp, vr,      &\n    !$omp         work1, work2, work3, work4, elec_temp, evdw_temp,            &\n    !$omp         force_local, ixyz, vx_tmp, vy_tmp, vz_tmp, nix, nix1, niy,   &\n    !$omp         niz, bsc_tmp, bscd_tmp, kk, iprocx, iprocy, qtmp, grid,      &\n    !$omp         half_grid, is, start, end, nizx, nizy, iatmcls, ltmp,        &\n    !$omp         efft_real, efft_imag, vfft_real, vfft_imag, force_local_lj)\n    !\n#ifdef OMP\n    id = omp_get_thread_num()\n#else\n    id = 0\n#endif\n\n    ! initialization\n    !\n    allocate(work1(ngridmax), work2(2*ngridmax), &\n             work3(ngridmax), work4(2*ngridmax))\n\n    start(1) = x_start\n    start(2) = y_start\n    start(3) = z_start\n    end(1) = x_end\n    end(2) = y_end\n    end(3) = z_end\n\n    ! Initialization of Q-fanction\n    !\n    do iz = 1, nlocalz\n      do iy = 1, nlocaly\n        do ix = 1, nlocalx\n          qdf(ix,iy,iz,id+1) = 0.0_wp\n          ldf(ix,iy,iz,id+1) = 0.0_wp\n        end do\n      end do\n    end do\n\n    ! Calculateing Q-fanction\n    !\n    grid(1:3) = real(ngrid(1:3),wp)\n    half_grid(1:3) = real(ngrid(1:3)/2,wp)\n\n    do icel = id+1, ncell_local, nthread\n      do i = 1, natom(icel)\n\n        qtmp = charge(i,icel)\n        iatmcls = atmcls(i,icel)\n        ltmp = nonb_lj6_factor(iatmcls)\n        vr(1:3) = coord(1:3,i,icel) * r_scale(1:3)\n        vr(1:3) = vr(1:3) + half_grid(1:3) &\n                - grid(1:3)*anint(vr(1:3)/grid(1:3))\n\n        do k = 1, 3\n          vr(k) = min(vr(k),grid(k)-0.000001_wp)\n          ii(k) = min(int(vr(k)),ngrid(k)-1)\n        end do\n\n        nix = 0\n        niy = 0\n        niz = 0\n!ocl nosimd\n        do ixyz = 1, n_bs\n          ixs = ii(1) - ixyz + 2\n          if (ixs \u003c= 0) ixs = ixs + ngrid(1)\n          if (ixs >= x_start .and. ixs \u003c= x_end) then\n            nix = nix + 1\n            vx_tmp(nix) = ixs - x_start + 1\n            is(nix,1) = ixyz\n          end if\n        end do\n\n!ocl nosimd\n        do ixyz = 1, n_bs\n          iys = ii(2) - ixyz + 2\n          if (iys \u003c= 0) iys = iys + ngrid(2)\n          if (iys >= y_start .and. iys \u003c= y_end) then\n            niy = niy + 1\n            vy_tmp(niy) = iys - y_start + 1\n            is(niy,2) = ixyz\n          end if\n        end do\n\n!ocl nosimd\n        do ixyz = 1, n_bs\n          izs = ii(3) - ixyz + 2\n          if (izs \u003c= 0) izs = izs + ngrid(3)\n          if (izs >= z_start .and. izs \u003c= z_end) then\n            niz = niz + 1\n            vz_tmp(niz) = izs - z_start + 1\n            is(niz,3) = ixyz\n          end if\n        end do\n\n        force(1,i,icel) = 1.0_wp\n\n        do k = 1, 3\n          vi(k,i,icel) = ii(k)\n          dv(k) = vr(k) - real(ii(k),wp)\n          call b_spline_dev_coef(n_bs, dv(k), bsc(1,k,i,icel), bscd(1,k,i,icel))\n        end do\n\n!ocl nosimd\n        do ix = 1, nix\n          ixyz = is(ix,1)\n          bsc_tmp(1,ix) = bsc(ixyz,1,i,icel)\n        end do\n!ocl nosimd\n        do iy = 1, niy\n          ixyz = is(iy,2)\n          bsc_tmp(2,iy) = bsc(ixyz,2,i,icel)\n        end do\n!ocl nosimd\n        do iz = 1, niz\n          ixyz = is(iz,3)\n          bsc_tmp(3,iz) = bsc(ixyz,3,i,icel)\n        end do\n\n!ocl nosimd\n        do iz = 1, niz\n          izs = vz_tmp(iz)\n          do iy = 1, niy\n            iys = vy_tmp(iy)\n!ocl norecurrence(qdf,ldf)\n            do ix = 1, nix\n              ixs = vx_tmp(ix)\n              qdf(ixs,iys,izs,id+1) = qdf(ixs,iys,izs,id+1)           &\n                                    + bsc_tmp(1,ix)*bsc_tmp(2,iy)     &\n                                     * bsc_tmp(3,iz)*qtmp   &\n                                     * bs_fact3\n              ldf(ixs,iys,izs,id+1) = ldf(ixs,iys,izs,id+1)           &\n                                    + bsc_tmp(1,ix)*bsc_tmp(2,iy)     &\n                                     * bsc_tmp(3,iz)*ltmp   &\n                                     * bs_fact3\n            end do\n          end do\n        end do\n      end do\n    end do\n\n    do icel = id+ncell_local+1, ncell, nthread\n      do i = 1, natom(icel)\n\n        qtmp = charge(i,icel)\n        iatmcls = atmcls(i,icel)\n        ltmp = nonb_lj6_factor(iatmcls)\n        vr(1:3) = coord(1:3,i,icel) * r_scale(1:3)\n        vr(1:3) = vr(1:3) + half_grid(1:3) &\n                - grid(1:3)*anint(vr(1:3)/grid(1:3))\n\n!ocl nosimd\n        do k = 1, 3\n          vr(k) = min(vr(k),grid(k)-0.000001_wp)\n          ii(k) = min(int(vr(k)),ngrid(k)-1)\n        end do\n\n        nix = 0\n        niy = 0\n        niz = 0\n\n        ixs = ii(1) - n_bs + 2\n        if (ixs \u003c= 0) ixs = ixs + ngrid(1)\n        if (ixs >= x_start .and. ixs \u003c= x_end) then\n          nix = nix + 1\n          vx_tmp(nix) = ixs - x_start + 1\n          is (nix,1) = n_bs\n        end if\n        ixs = ii(1) + 1\n        if (ixs \u003c= 0) ixs = ixs + ngrid(1)\n        if (ixs >= x_start .and. ixs \u003c= x_end) then\n          nix = nix + 1\n          vx_tmp(nix) = ixs - x_start + 1\n          is (nix,1) = 1\n        end if\n        if (nix == 0) cycle\n\n        iys = ii(2) - n_bs + 2\n        if (iys \u003c= 0) iys = iys + ngrid(2)\n        if (iys >= y_start .and. iys \u003c= y_end) then\n          niy = niy + 1\n          vy_tmp(niy) = iys - y_start + 1\n          is (niy,2) = n_bs\n        end if\n        iys = ii(2) + 1\n        if (iys \u003c= 0) iys = iys + ngrid(2)\n        if (iys >= y_start .and. iys \u003c= y_end) then\n          niy = niy + 1\n          vy_tmp(niy) = iys - y_start + 1\n          is (niy,2) = 1\n        end if\n        if (niy == 0) cycle\n\n        izs = ii(3) - n_bs + 2\n        if (izs \u003c= 0) izs = izs + ngrid(3)\n        if (izs >= z_start .and. izs \u003c= z_end) then\n          niz = niz + 1\n          vz_tmp(niz) = izs - z_start + 1\n          is (niz,3) = n_bs\n        end if\n        izs = ii(3) + 1\n        if (izs \u003c= 0) izs = izs + ngrid(3)\n        if (izs >= z_start .and. izs \u003c= z_end) then\n          niz = niz + 1\n          vz_tmp(niz) = izs - z_start + 1\n          is (niz,3) = 1\n        end if\n        if (niz == 0) cycle\n\n!ocl nosimd\n        do ixyz = 2, n_bs-1\n          ixs = ii(1) - ixyz + 2\n          if (ixs \u003c= 0) ixs = ixs + ngrid(1)\n          if (ixs >= x_start .and. ixs \u003c= x_end) then\n            nix = nix + 1\n            vx_tmp(nix) = ixs - x_start + 1\n            is(nix,1) = ixyz\n          end if\n        end do\n\n!ocl nosimd\n        do ixyz = 2, n_bs-1\n          iys = ii(2) - ixyz + 2\n          if (iys \u003c= 0) iys = iys + ngrid(2)\n          if (iys >= y_start .and. iys \u003c= y_end) then\n            niy = niy + 1\n            vy_tmp(niy) = iys - y_start + 1\n            is(niy,2) = ixyz\n          end if\n        end do\n\n!ocl nosimd\n        do ixyz = 2, n_bs-1\n          izs = ii(3) - ixyz + 2\n          if (izs \u003c= 0) izs = izs + ngrid(3)\n          if (izs >= z_start .and. izs \u003c= z_end) then\n            niz = niz + 1\n            vz_tmp(niz) = izs - z_start + 1\n            is(niz,3) = ixyz\n          end if\n        end do\n\n        force(1,i,icel) = 1.0_wp\n\n        do k = 1, 3\n          vi(k,i,icel) = ii(k)\n          dv(k) = vr(k) - real(ii(k),wp)\n          call b_spline_dev_coef(n_bs, dv(k), bsc(1,k,i,icel), bscd(1,k,i,icel))\n        end do\n\n!ocl nosimd\n        do ix = 1, nix\n          ixyz = is(ix,1)\n          bsc_tmp(1,ix) = bsc(ixyz,1,i,icel)\n        end do\n!ocl nosimd\n        do iy = 1, niy\n          ixyz = is(iy,2)\n          bsc_tmp(2,iy) = bsc(ixyz,2,i,icel)\n        end do\n!ocl nosimd\n        do iz = 1, niz\n          ixyz = is(iz,3)\n          bsc_tmp(3,iz) = bsc(ixyz,3,i,icel)\n        end do\n\n!ocl nosimd\n        do iz = 1, niz\n          izs = vz_tmp(iz)\n          do iy = 1, niy\n            iys = vy_tmp(iy)\n!ocl norecurrence(qdf)\n             do ix = 1, nix\n               ixs = vx_tmp(ix)\n              qdf(ixs,iys,izs,id+1) = qdf(ixs,iys,izs,id+1)           &\n                                    + bsc_tmp(1,ix)*bsc_tmp(2,iy)     &\n                                     * bsc_tmp(3,iz)*qtmp   &\n                                     * bs_fact3\n              ldf(ixs,iys,izs,id+1) = ldf(ixs,iys,izs,id+1)           &\n                                    + bsc_tmp(1,ix)*bsc_tmp(2,iy)     &\n                                     * bsc_tmp(3,iz)*ltmp   &\n                                     * bs_fact3\n            end do\n          end do\n        end do\n      end do\n    end do\n    !$omp barrier\n    do iproc = 1, nthread\n      !$omp do\n      do iz = 1, nlocalz\n        do iy = 1, nlocaly\n          k = (iy-1)*nlocalx + (iz-1)*nlocalx*nlocaly\n!ocl nosimd\n          do ix = 1, nlocalx\n            qdf_real(k+ix) = qdf_real(k+ix) + qdf(ix,iy,iz,iproc)\n            ldf_real(k+ix) = ldf_real(k+ix) + ldf(ix,iy,iz,iproc)\n          end do\n        end do\n      end do\n    end do\n\n    ! FFT (forward)\n    !\n    !$omp barrier\n    !$omp master\n#ifdef HAVE_MPI_GENESIS\n    call mpi_alltoall(qdf_real, nlocalx*nlocaly*nlocalz/nprocx, mpi_wp_real, &\n                      qdf_work, nlocalx*nlocaly*nlocalz/nprocx, mpi_wp_real, &\n                      grid_commx, ierror)\n    call mpi_alltoall(ldf_real, nlocalx*nlocaly*nlocalz/nprocx, mpi_wp_real, &\n                      ldf_work, nlocalx*nlocaly*nlocalz/nprocx, mpi_wp_real, &\n                      grid_commx, ierror)\n#else\n    qdf_work(1:nlocalx*nlocaly*nlocalz,1) = qdf_real(1:nlocalx*nlocaly*nlocalz)\n    ldf_work(1:nlocalx*nlocaly*nlocalz,1) = ldf_real(1:nlocalx*nlocaly*nlocalz)\n#endif\n    !$omp end master\n    !$omp barrier\n\n    niz = nlocalz / nprocx\n    nix  = (nlocalx1-1)/nprocy\n    nix1 = nix + 1\n    niy = ngrid(2)/nprocz\n    call fft3d_2d_alltoall_lj(qdf_work, ftqdf, ftqdf, ftqdf, ftqdf_work,      &\n                              ftqdf_work, ftqdf_work2, work1, work2,          &\n                              ldf_work, ftldf, ftldf, ftldf, ftldf_work,      &\n                              ftldf_work, ftldf_work2, work3, work4,          &\n                              nlocalx, nlocaly, nlocalz, ngrid(1), ngrid(2),  &\n                              ngrid(3), nprocx, nprocy, nprocz, nix, nix1,    &\n                              niz, niy, id, nthread, my_x_rank, grid_commz,   &\n                              grid_commxy)\n\n    ! Energy calculation\n    !\n    iproc = my_z_rank + 1\n\n    !$omp barrier\n    !$omp do\n    do ix = 1, nix\n      do iy = 1, niy\n        elec_temp = 0.0_wp\n        evdw_temp = 0.0_wp\n        vxx = 0.0_wp\n        vyy = 0.0_wp\n        vzz = 0.0_wp\n        do iz = 1, ngrid(3)\n          efft_real = real(ftqdf_work2(iz,iy,ix),wp)\n          efft_imag = imag(ftqdf_work2(iz,iy,ix))\n          vfft_real = real(ftldf_work2(iz,iy,ix),wp)\n          vfft_imag = imag(ftldf_work2(iz,iy,ix))\n          tqq = efft_real*efft_real + efft_imag*efft_imag\n          tqq = tqq * theta(iz,iy,ix) * vol_fact4\n          elec_temp = elec_temp + tqq\n          tll = vfft_real*vfft_real + vfft_imag*vfft_imag\n          tll = tll * vol_fact4_lj\n          evdw_temp = evdw_temp - tll*theta_lj(iz,iy,ix)\n          vxx = vxx + tqq * (1.0_wp+vir_fact(iz,iy,ix)*gx(ix)*gx(ix))\n          vyy = vyy + tqq * (1.0_wp+vir_fact(iz,iy,ix)*gy(iy)*gy(iy))\n          vzz = vzz + tqq * (1.0_wp+vir_fact(iz,iy,ix)*gz(iz)*gz(iz))\n          vxx = vxx - tll * (theta_lj(iz,iy,ix)+vir_fact_lj(iz,iy,ix)*gx(ix)*gx(ix))\n          vyy = vyy - tll * (theta_lj(iz,iy,ix)+vir_fact_lj(iz,iy,ix)*gy(iy)*gy(iy))\n          vzz = vzz - tll * (theta_lj(iz,iy,ix)+vir_fact_lj(iz,iy,ix)*gz(iz)*gz(iz))\n        end do\n        eelec(id+1) = eelec(id+1) + elec_temp\n        evdw (id+1) = evdw (id+1) + evdw_temp\n        virial(1,1,id+1) = virial(1,1,id+1) + vxx\n        virial(2,2,id+1) = virial(2,2,id+1) + vyy\n        virial(3,3,id+1) = virial(3,3,id+1) + vzz\n      end do\n    end do\n\n    if(my_x_rank == 0 .and. my_y_rank == 0) then\n\n      !$omp do\n      do iy = 1, niy\n        elec_temp = 0.0_wp\n        evdw_temp = 0.0_wp\n        vxx = 0.0_wp\n        vyy = 0.0_wp\n        vzz = 0.0_wp\n        do iz = 1, ngrid(3)\n          efft_real = real(ftqdf_work2(iz,iy,1),wp)\n          efft_imag = imag(ftqdf_work2(iz,iy,1))\n          vfft_real = real(ftldf_work2(iz,iy,1),wp)\n          vfft_imag = imag(ftldf_work2(iz,iy,1))\n          tqq = efft_real*efft_real + efft_imag*efft_imag\n          tqq = tqq * theta(iz,iy,1) * vol_fact2\n          elec_temp = elec_temp - tqq\n          tll = vfft_real*vfft_real + vfft_imag*vfft_imag\n          tll = tll * vol_fact2_lj\n          evdw_temp = evdw_temp + tll*theta_lj(iz,iy,1)\n          vxx = vxx - tqq * (1.0_wp+vir_fact(iz,iy,1)*gx(1)*gx(1))\n          vyy = vyy - tqq * (1.0_wp+vir_fact(iz,iy,1)*gy(iy)*gy(iy))\n          vzz = vzz - tqq * (1.0_wp+vir_fact(iz,iy,1)*gz(iz)*gz(iz))\n          vxx = vxx  &\n              + tll*(theta_lj(iz,iy,1)+vir_fact_lj(iz,iy,1)*gx(1 )*gx(1 ))\n          vyy = vyy  &\n              + tll*(theta_lj(iz,iy,1)+vir_fact_lj(iz,iy,1)*gy(iy)*gy(iy))\n          vzz = vzz  &\n              + tll*(theta_lj(iz,iy,1)+vir_fact_lj(iz,iy,1)*gz(iz)*gz(iz))\n        end do\n        do iz = 1, ngrid(3)\n          efft_real = real(ftqdf_work2(iz,iy,nix1),wp)\n          efft_imag = imag(ftqdf_work2(iz,iy,nix1))\n          vfft_real = real(ftldf_work2(iz,iy,nix1),wp)\n          vfft_imag = imag(ftldf_work2(iz,iy,nix1))\n          tqq = efft_real*efft_real + efft_imag*efft_imag\n          tqq = tqq * theta(iz,iy,nix1) * vol_fact2\n          elec_temp = elec_temp + tqq\n          tll = vfft_real*vfft_real + vfft_imag*vfft_imag\n          tll = tll * vol_fact2_lj\n          evdw_temp = evdw_temp - tll*theta_lj(iz,iy,nix1)\n          vxx = vxx + tqq * (1.0_wp+vir_fact(iz,iy,nix1)*gx(nix1)*gx(nix1))\n          vyy = vyy + tqq * (1.0_wp+vir_fact(iz,iy,nix1)*gy(iy)*gy(iy))\n          vzz = vzz + tqq * (1.0_wp+vir_fact(iz,iy,nix1)*gz(iz)*gz(iz))\n          vxx = vxx  &\n              - tll*(theta_lj(iz,iy,nix1)+vir_fact_lj(iz,iy,nix1)*gx(nix1)*gx(nix1))\n          vyy = vyy  &\n              - tll*(theta_lj(iz,iy,nix1)+vir_fact_lj(iz,iy,nix1)*gy(iy)*gy(iy))\n          vzz = vzz  &\n              - tll*(theta_lj(iz,iy,nix1)+vir_fact_lj(iz,iy,nix1)*gz(iz)*gz(iz))\n        end do\n        eelec(id+1) = eelec(id+1) + elec_temp\n        evdw (id+1) = evdw (id+1) + evdw_temp\n        virial(1,1,id+1) = virial(1,1,id+1) + vxx\n        virial(2,2,id+1) = virial(2,2,id+1) + vyy\n        virial(3,3,id+1) = virial(3,3,id+1) + vzz\n      end do\n    end if\n\n    ! add self dispersion term\n    !\n    !$omp master\n    if (my_city_rank == 0) then\n      temp    = PI*sqrt(PI)*alpha3*inv_volume/(6.0_wp)*enefunc%pme_dispersion_self1\n      evdw(1) = evdw(1) - temp\n      evdw(1) = evdw(1) + alpha6/12.0_wp*enefunc%pme_dispersion_self2\n      virial(1,1,1) = virial(1,1,1) - temp\n      virial(2,2,1) = virial(2,2,1) - temp\n      virial(3,3,1) = virial(3,3,1) - temp\n    end if\n    !$omp end master\n\n    ! F^-1[Th]*F^-1[Q] (=X)\n    !\n    !$omp barrier\n    !$omp do\n    do ix = 1, nix\n      do iy = 1, niy\n        do iz = 1, ngrid(3)\n          ftqdf_work2(iz,iy,ix) = ftqdf_work2(iz,iy,ix) &\n                                  * cmplx(theta(iz,iy,ix),0.0_wp,kind=wp)\n          ftldf_work2(iz,iy,ix) = ftldf_work2(iz,iy,ix) &\n                                  * cmplx(theta_lj(iz,iy,ix),0.0_wp,kind=wp)\n        end do\n      end do\n    end do\n    if(my_x_rank == 0 .and. my_y_rank == 0) then\n      ix = nix1\n      !$omp do\n      do iy = 1, niy\n        do iz = 1, ngrid(3)\n          ftqdf_work2(iz,iy,ix) = ftqdf_work2(iz,iy,ix) * cmplx(theta(iz,iy,ix),0.0_wp,kind=wp)\n          ftldf_work2(iz,iy,ix) = ftldf_work2(iz,iy,ix) * cmplx(theta_lj(iz,iy,ix),0.0_wp,kind=wp)\n        end do\n      end do\n    end if\n\n    ! FFT(backward)\n    ! \n    !$omp barrier\n    call bfft3d_2d_alltoall_lj(qdf_work, qdf_real, ftqdf, ftqdf, ftqdf, &\n                               ftqdf_work, ftqdf_work, ftqdf_work2,     &\n                               work1, work2,                            &\n                               ldf_work, ldf_real, ftldf, ftldf, ftldf, &\n                               ftldf_work, ftldf_work, ftldf_work2,     &\n                               work3, work4,                            &\n                               nlocalx, nlocaly, nlocalz,               &\n                               ngrid(1), ngrid(2), ngrid(3),            &\n                               nprocx, nprocy, nprocz, nix, nix1,       &\n                               niy, niz, id, nthread, grid_commx,       &\n                               grid_commz, grid_commxy)\n    !$omp barrier\n\n    do iz = id+1, nlocalz, nthread\n      do iy = 1, nlocaly\n        k = (iy-1)*nlocalx + (iz-1)*nlocalx*nlocaly\n        do ix = 1, nlocalx\n          qdf(ix,iy,iz,1) = qdf_real(k+ix)\n          ldf(ix,iy,iz,1) = ldf_real(k+ix)\n        end do\n      end do\n    end do\n\n    !$omp barrier\n\n    do icel = id+1, ncell_local, nthread\n      do i = 1, natom(icel)\n\n        force_local(1:3) = 0.0_wp\n        force_local_lj(1:3) = 0.0_wp\n        qtmp = charge(i,icel)\n        iatmcls = atmcls(i,icel)\n        ltmp = nonb_lj6_factor(iatmcls)*vol_fact4_lj*bs_fact3d\n\n!ocl nosimd\n        do k = 1, 3\n          ii(k) = vi(k,i,icel)\n        end do\n\n        nix=0\n        niy=0\n        niz=0\n\n!ocl nosimd\n        do ixyz = 1, n_bs\n\n          ixs = ii(1) - (ixyz-1) + 1\n          iys = ii(2) - (ixyz-1) + 1\n          izs = ii(3) - (ixyz-1) + 1\n          if (ixs \u003c= 0) ixs = ixs + ngrid(1)\n          if (iys \u003c= 0) iys = iys + ngrid(2)\n          if (izs \u003c= 0) izs = izs + ngrid(3)\n\n          if (ixs >= x_start .and. ixs \u003c= x_end) then\n            nix = nix + 1\n            vx_tmp(nix) = ixs - x_start + 1\n            bsc_tmp(1,nix)  = bsc(ixyz,1,i,icel)\n            bscd_tmp(1,nix) = bscd(ixyz,1,i,icel)\n          end if\n\n          if (iys >= y_start .and. iys \u003c= y_end) then\n            niy = niy + 1\n            vy_tmp(niy) = iys - y_start + 1\n            bsc_tmp(2,niy)  = bsc(ixyz,2,i,icel)\n            bscd_tmp(2,niy) = bscd(ixyz,2,i,icel)\n          end if\n\n          if (izs >= z_start .and. izs \u003c= z_end) then\n            niz = niz + 1\n            vz_tmp(niz) = izs - z_start + 1\n            bsc_tmp(3,niz)  = bsc(ixyz,3,i,icel)\n            bscd_tmp(3,niz) = bscd(ixyz,3,i,icel)\n          end if\n        end do\n\n!ocl nosimd\n        do iz = 1, niz\n          izs = vz_tmp(iz)\n          do iy = 1, niy\n            iys = vy_tmp(iy)\n            do ix = 1, nix\n              ixs = vx_tmp(ix)\n\n              force_local(1) = force_local(1)            &\n                  + bscd_tmp(1,ix)*bsc_tmp(2,iy)         &\n                  * bsc_tmp(3,iz)*qdf(ixs,iys,izs,1)\n              force_local(2) = force_local(2)            &\n                  + bsc_tmp(1,ix)*bscd_tmp(2,iy)         &\n                  * bsc_tmp(3,iz)*qdf(ixs,iys,izs,1)\n              force_local(3) = force_local(3)            &\n                  + bsc_tmp(1,ix)*bsc_tmp(2,iy)          &\n                  * bscd_tmp(3,iz)*qdf(ixs,iys,izs,1)\n              force_local_lj(1) = force_local_lj(1)      &\n                  + bscd_tmp(1,ix)*bsc_tmp(2,iy)         &\n                  * bsc_tmp(3,iz)*ldf(ixs,iys,izs,1)\n              force_local_lj(2) = force_local_lj(2)      &\n                  + bsc_tmp(1,ix)*bscd_tmp(2,iy)         &\n                  * bsc_tmp(3,iz)*ldf(ixs,iys,izs,1)\n              force_local_lj(3) = force_local_lj(3)      &\n                  + bsc_tmp(1,ix)*bsc_tmp(2,iy)          &\n                  * bscd_tmp(3,iz)*ldf(ixs,iys,izs,1)\n            end do\n          end do\n        end do\n\n        force(1:3,i,icel) = - force_local(1:3) * &\n                              qtmp*r_scale(1:3)*vol_fact4*bs_fact3d &\n                            + force_local_lj(1:3)*ltmp*r_scale(1:3)\n\n      end do\n    end do\n\n    do icel = id+ncell_local+1, ncell, nthread\n      do i = 1, natom(icel)\n\n        if (abs(force(1,i,icel)) \u003c EPS) cycle\n\n        force_local(1:3) = 0.0_wp\n        force_local_lj(1:3) = 0.0_wp\n        qtmp = charge(i,icel)\n        iatmcls = atmcls(i,icel)\n        ltmp = nonb_lj6_factor(iatmcls)*vol_fact4_lj*bs_fact3d\n\n!ocl nosimd\n        do k = 1, 3\n          ii(k) = vi(k,i,icel)\n        end do\n\n        nix=0\n        niy=0\n        niz=0\n\n!ocl nosimd\n        do ixyz = 1, n_bs\n\n          ixs = ii(1) - (ixyz-1) + 1\n          iys = ii(2) - (ixyz-1) + 1\n          izs = ii(3) - (ixyz-1) + 1\n          if (ixs \u003c= 0) ixs = ixs + ngrid(1)\n          if (iys \u003c= 0) iys = iys + ngrid(2)\n          if (izs \u003c= 0) izs = izs + ngrid(3)\n\n          if (ixs >= x_start .and. ixs \u003c= x_end) then\n            nix = nix + 1\n            vx_tmp(nix) = ixs - x_start + 1\n            bsc_tmp(1,nix)  = bsc(ixyz,1,i,icel)\n            bscd_tmp(1,nix) = bscd(ixyz,1,i,icel)\n          end if\n\n          if (iys >= y_start .and. iys \u003c= y_end) then\n            niy = niy + 1\n            vy_tmp(niy) = iys - y_start + 1\n            bsc_tmp(2,niy)  = bsc(ixyz,2,i,icel)\n            bscd_tmp(2,niy) = bscd(ixyz,2,i,icel)\n          end if\n\n          if (izs >= z_start .and. izs \u003c= z_end) then\n            niz = niz + 1\n            vz_tmp(niz) = izs - z_start + 1\n            bsc_tmp(3,niz)  = bsc(ixyz,3,i,icel)\n            bscd_tmp(3,niz) = bscd(ixyz,3,i,icel)\n          end if\n        end do\n\n!ocl nosimd\n        do iz = 1, niz\n          izs = vz_tmp(iz)\n          do iy = 1, niy\n            iys = vy_tmp(iy)\n            do ix = 1, nix\n              ixs = vx_tmp(ix)\n\n              force_local(1) = force_local(1)            &\n                  + bscd_tmp(1,ix)*bsc_tmp(2,iy)         &\n                  * bsc_tmp(3,iz)*qdf(ixs,iys,izs,1)\n              force_local(2) = force_local(2)            &\n                  + bsc_tmp(1,ix)*bscd_tmp(2,iy)         &\n                  * bsc_tmp(3,iz)*qdf(ixs,iys,izs,1)\n              force_local(3) = force_local(3)            &\n                  + bsc_tmp(1,ix)*bsc_tmp(2,iy)          &\n                  * bscd_tmp(3,iz)*qdf(ixs,iys,izs,1)\n              force_local_lj(1) = force_local_lj(1)      &\n                  + bscd_tmp(1,ix)*bsc_tmp(2,iy)         &\n                  * bsc_tmp(3,iz)*ldf(ixs,iys,izs,1)\n              force_local_lj(2) = force_local_lj(2)      &\n                  + bsc_tmp(1,ix)*bscd_tmp(2,iy)         &\n                  * bsc_tmp(3,iz)*ldf(ixs,iys,izs,1)\n              force_local_lj(3) = force_local_lj(3)      &\n                  + bsc_tmp(1,ix)*bsc_tmp(2,iy)          &\n                  * bscd_tmp(3,iz)*ldf(ixs,iys,izs,1)\n            end do\n          end do\n        end do\n\n        force(1:3,i,icel) = - force_local(1:3) * &\n                              qtmp*r_scale(1:3)*vol_fact4*bs_fact3d &\n                            + force_local_lj(1:3)*ltmp*r_scale(1:3)\n\n      end do\n    end do\n\n    deallocate(work1, work2, work3, work4)\n\n    !$omp end parallel\n\n    return\n\n  end subroutine pme_recip_noopt_2dalltoall_lj\n\nend module sp_energy_pme_noopt_2dalltoall_mod\n";
